mapper.select:
SELECT COUNT(*)
 FROM USERS
WHERE USER_ID = #{userId}

mapper.insert:
INSERT INTO USERS
           (
             USER_ID
           , PASSWD
           , USER_NM
           , HP_NO
           , ADDR
           , DTL_ADDR
           , CREATED_AT
           , ROLE
           , FRST_REG_EMP_NO
           , FRST_REG_DTM
           , LAST_MOD_EMP_NO
           , LAST_MOD_DTM
           )
VALUES     (
             #{userId}
           , #{passwd}
           , #{userNm}
           , #{hpNo}
           , #{addr}
           , #{dtlAddr}
           , CURRENT_TIMESTAMP
           , 'USER'
           , #{userId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           , #{userId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           )
